        // We can craft a low-level call to c.collateral() providing calldata that appends the immutable args in the tail so that
        // _getImmutableArgsOffset reads them. We need to call the public function selector followed by any calldata (none) then append the immutable args and their length trailer as the clone runtime expects.

        // The clone's _getImmutableArgsOffset expects the last two bytes of calldata to hold the length of the immutable args area (shifted into a word by calldataload).
        // The clone creation routine in reference stores extraLength (data.length) plus 2 in creation code and puts at the end a single byte (extraLength) shifted; but the _getImmutableArgsOffset reads:
        // sub(calldatasize(), add(shr(240, calldataload(sub(calldatasize(), 2))), 2))
        // That means the last two bytes of calldata include a word where the high-order byte (shr(240, ...)) equals the immutable args length.
        // To satisfy this, we append args and then a 2-byte trailer where the high byte equals args.length + 2 (as used by clone). For simplicity, set trailer high byte to uint8(args.length + 2).

        // Prepare function selector for collateral(): bytes4(keccak256("collateral()"))
        bytes4 sel = bytes4(keccak256("collateral()"));
        bytes memory callData = abi.encodePacked(sel);

        // Append the immutable args and then a 2-byte trailer word where the leading byte encodes args.length+2
        uint16 trailerHigh = uint16(uint8(args.length + 2));
        // trailer is 2 bytes: [highByte][lowByte]. low byte can be zero.
        bytes memory trailer = abi.encodePacked(bytes1(bytes1(uint8(trailerHigh))), bytes1(uint8(0)));

        bytes memory full = bytes.concat(callData, args, trailer);

        // Now perform low-level staticcall to c with crafted calldata. collateral() is a view (pure), so staticcall is appropriate.
        (bool ok, bytes memory ret) = address(c).staticcall(full);

        // If the call succeeded, decode returned address; if it reverted, set ok=false.
        address returnedCollateral;
        if (ok && ret.length >= 32) {
            returnedCollateral = abi.decode(ret, (address));
        } else {
            // If it reverted or returned unexpected data, treat as zero
            returnedCollateral = address(0);
        }

        // The general property: when reading the collateral immutable arg at offset 0x14, the returned address must equal the 20-byte word placed in args at bytes 0x14..0x27.
        // Construct what the reference expects: args layout: owner (0x00-0x13), collateral (0x14-0x27), debt (0x28-0x3b), factory (0x3c-0x4f)
        // Since we built args as abi.encodePacked(owner, collateral, debt, factory) with 20-byte addresses, collateralAddr should be read by offset 0x14.

        // Assert that the returned address equals the collateralAddr we placed.
        // This holds for the correct/reference contract for all inputs; the mutant that reads at 0x10 will sometimes read a different address (owner + leading bytes), causing inequality for some fuzz inputs.
        assertTrue(returnedCollateral == collateralAddr);
    }
}

