contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz parameters: two uint256 values that will be interpreted as two adjacent 32-byte words
    // in the immutable args region. The reference reads the address at offset 0x14 (i.e. bytes 20..39
    // of the first word/second word boundary); the mutant reads at 0x10 (bytes 16..35). We make
    // a general admissible domain by allowing any two words, but we assume they are such that when
    // interpreted at offset 0x14 they form a valid address (non-zero) — this keeps the domain wide.
    function testFuzz_property(uint256 w1, uint256 w2) public {
        // Compose immutable args bytes where the relevant area contains w1 followed by w2.
        // We will construct a clone creation data area matching the layout expected by the clone
        // factory: but we do not need to actually use the cloning machinery — collateral() simply
        // reads immutable args from the contract's own calldata at offsets computed by
        // _getImmutableArgsOffset(), which in a standalone contract c (deployed with no
        // immutable args) will read calldatasize-derived values. To exercise the pure getter
        // behavior, we instead call the public view collateral() via a low-level staticcall to a
        // fabricated calldata which simulates the clone's calldata layout: we cannot change c's
        // stored immutable args, so instead we call collateral() with arbitrary calldata and use
        // try/catch to detect if the return address matches our expectation.
        // However, collateral() is a simple pure getter that uses _getImmutableArgsOffset which
        // reads calldatasize and calldataload; thus its return depends on the calldata passed to
        // the call. We'll craft calldata such that at offsets 0x10 and 0x14 inside the immutable
        // args region the two 20-byte addresses are different; the reference should return the
        // address at offset 0x14 regardless of w1/w2. We assert that calling collateral() via
        // staticcall returns the address equal to the 20 low bytes starting at byte offset 0x14
        // inside our provided calldata.

        // Build calldata for calling collateral(): function selector (4 bytes) + padding +
        // append fake immutable args at the end so _getImmutableArgsOffset picks them up.
        bytes memory sig = abi.encodeWithSelector(C.collateral.selector);

        // Construct two consecutive words in memory: w1 then w2. We'll place them at the end
        // of calldata so that offsets relative to calldatasize()-... line up; We need the word
        // containing the 0x14 offset to be composed from bytes across the boundary of w1/w2
        // so the test actually distinguishes offset 0x10 vs 0x14.

        bytes memory imm = abi.encodePacked(w1, w2);

        // full calldata = sig + imm
        bytes memory full = bytes.concat(sig, imm);

        // For safety, ensure calldata is large enough for the internal offset computations.
        // Keep admissible domain wide: require that imm length >= 0x30 so offsets 0x10 and 0x14 are valid
        vm.assume(imm.length >= 0x30);

        // Now perform a low-level staticcall to c with our crafted calldata
        (bool ok, bytes memory ret) = address(c).staticcall(full);

        // The call should succeed for the reference contract (pure getter), but keep it general
        // and treat failure as test failure (we assert based on returned data below).
        require(ok, "call failed");

        // Parse returned address from ret (ABI-encoded as address)
        address returned;
        // collateral() returns (ERC20) which is address sized; ABI return is 32 bytes with the address in low 20 bytes
        assembly {
            returned := mload(add(ret, 32))
        }

        // Now compute expected address by reading the 20 bytes at offset 0x14 of the immutable area
        // within our full calldata. The immutable args are appended after the 4-byte selector.
        // So the byte index of the immutable area start is 4.
        uint256 immStart = 4;
        // offset 0x14 inside immutable args corresponds to immStart + 0x14
        uint256 addrByteIndex = immStart + 0x14;

        // Ensure we can read 20 bytes starting there
        vm.assume(full.length >= addrByteIndex + 20);

        // Read 32-byte word containing the 20-byte address (we read the 32-byte word starting at floor(addrByteIndex/32)*32)
        uint256 wordIndex = addrByteIndex / 32;
        uint256 wordStart = wordIndex * 32;
        // Copy 32 bytes from that position
        bytes32 word;
        assembly {
            word := mload(add(add(full, 32), wordStart))
        }

        // Now compute the offset within the word where our address's first byte resides
        uint256 offsetInWord = addrByteIndex % 32;
        // Extract the 20-byte address spanning possibly across two words. To simplify, construct the 32-byte
        // window starting at addrByteIndex and load 32 bytes by reading two words and combining.
        bytes32 wA;
        bytes32 wB;
        assembly {
            wA := mload(add(add(full, 32), wordStart))
            wB := mload(add(add(full, 32), add(wordStart, 32)))
        }
        // Build a 64-byte buffer concatenated as wA||wB, then shift left by offsetInWord*8 to align address
        bytes32 high = wA;
        bytes32 low = wB;
        bytes memory concat = abi.encodePacked(high, low);
        // Now the address starts at byte offset offsetInWord inside concat; extract 20 bytes
        uint256 extracted;
        assembly {
            extracted := mload(add(add(concat, 32), offsetInWord))
        }
        // Mask to low 20 bytes
        address expected = address(uint160(uint256(extracted) >> (12 * 8)));

        // The single assertion: the reference contract's collateral() returns the address located
        // at immutable offset 0x14 inside the calldata we supplied. This is a universal property
        // of the reference; the mutant (reading at 0x10) will differ for some choices of w1,w2
        // where the 20 bytes at 0x10 and 0x14 are not identical. We therefore assert equality here.
        assertTrue(returned == expected);
    }
}

