// Minimal deployer that clones an implementation and appends immutable args (a simplified version tailored to this test).
contract MinimalDeployer {
    function clone(address implementation, bytes memory data) public returns (address instance) {
        // We'll create a very small runtime that simply delegatescall to implementation and keeps appended immutable args accessible via _getImmutableArgsOffset logic used by Clone.
        bytes memory creationCode = hex"612f80600a3d3981f3"; // minimal proxy-ish; for the purpose of this exercise we reuse a simple create code that will not work fully,
