pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz the caller address to ensure generality; we just need at least one fuzzed param.
    function testFuzz_property(address caller) public {
        // Keep domain wide but non-zero caller to avoid trivial zero-address assumptions
        vm.assume(caller != address(0));

        // Call the public getter debt() and observe its returned address (as ERC20)
        ERC20 d = c.debt();
        // The general rule: the reference returns a non-zero address for debt(); the mutant returns address(0).
        // Single assertion: debt() must not be the zero address.
        assertTrue(address(d) != address(0));
    }
}

