pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address maybe) public {
        // fuzzed parameter 'maybe' is unused but required to let fuzzer search space
        // The general property: c.debt() must return a non-zero address for the reference.
        // Call the external view and assert it is non-zero.
        try c.debt() returns (address addr) {
            assertTrue(addr != address(0));
        } catch {
            // If calling debt() reverts (it shouldn't), consider that a failing case
            assertTrue(false);
        }
    }
}
